function show(string $name, string $content): void
{
    file_put_contents($name, $content);
    $o = new SplFileObject($name);
    $seen = [];
    foreach ($o as $k => $line) {
        $seen[] = $k . "=" . var_export($line, true);
    }
    echo str_pad(var_export($content, true), 14), " -> ", count($seen), " [", implode(", ", $seen), "]\n";
    unlink($name);
}
